import{z as A,x as d,o as t,c as B,q as l,j as i,D as a,d as o,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"字节回退","description":"","frontmatter":{"title":"字节回退","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/byte-fallback.md","filePath":"llm/byte-fallback.md","lastUpdated":1791413859000}'),s={name:"llm/byte-fallback.md"};function c(p,e,m,h,T,D){const E=d("Mermaid");return t(),B("div",null,[e[2]||(e[2]=l('<h1 id="字节回退" tabindex="-1">字节回退 <a class="header-anchor" href="#字节回退" aria-label="Permalink to &quot;字节回退&quot;">​</a></h1><div class="epigraph"><p>把词表里没有的字符拆成 UTF-8 字节，用 256 个字节符号拼回去，模型就不必为每一个未见码点准备一个 UNK。</p><footer>—— 据 Kudo &amp; Richardson，SentencePiece，EMNLP 2018；对照 Touvron 等，LLaMA，2023 整理</footer></div><p><a href="/llm/pretokenization-regex">上一课</a>用正则把文本切成块，再在块内合并。块内若仍出现词表没有的 Unicode 字符，Sennrich 式字符表会落到 UNK，整块信息被一个编号吞掉。本课不重讲正则，也不重讲 <a href="/llm/bpe-merge-rule">BPE</a> 的焊对顺序。缺口是：闭合字母表如何覆盖开放的 Unicode，而不把词表撑到码点级。SentencePiece 的字节回退（byte fallback）把未见字符拆成 UTF-8 字节符号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/tokenizer-design">分词器设计</a>已经区分字节级 BPE 与字符级 BPE。GPT-2 把任意 UTF-8 先映到 256 个原子再合并，训练时几乎没有 UNK。SentencePiece 默认词表却常从 Unicode 字符起步：常见汉字、拉丁字母进表，罕见符号、emoji、私用区、损坏字节进不了表。预分词正则不会帮你：它只切块，不保证块里每个码点都有编号。</p><p>UNK 的危害不是「少一个词」，而是训练与推理的信息不对称。训练语料若很少出现某字符，词表构建会把它丢掉；上线后用户一贴，整段被 UNK，梯度从未教过模型这个位置该读什么。需要一条确定的退路：任何码点都能写成已有符号的序列，且能无损拼回。</p><h3 id="_256-个字节不是-256-个「字母」" tabindex="-1">256 个字节不是 256 个「字母」 <a class="header-anchor" href="#_256-个字节不是-256-个「字母」" aria-label="Permalink to &quot;256 个字节不是 256 个「字母」&quot;">​</a></h3><p>UTF-8 是变长编码。一个 BMP 汉字三字节，一个 emoji 可能四字节。回退之后，表面上「一个字」会变成三四个 token，fertility 立刻上升。这是覆盖换长度，不是免费的万能词表。后课会把这种膨胀计进公平性；本课只保证「能拼回去」。</p>',8)),(t(),i(r,null,{default:a(()=>[n(E,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%90%8C%E4%B8%80%E5%8F%A5%E8%AF%9D%E9%87%8C%E7%9A%84%E4%B8%A4%E4%B8%AA%E5%AD%97%E7%AC%A6%22%5D%20--%3E%20A%5B%22%E5%B8%B8%E8%A7%81%E5%AD%97%E3%80%8C%E4%B8%AD%E3%80%8D%EF%BC%9A%E5%9C%A8%E8%AF%8D%E8%A1%A8%22%5D%0A%20%20IN%20--%3E%20B%5B%22%E7%94%9F%E5%83%BB%E5%AD%97%E6%88%96%20emoji%EF%BC%9A%E4%B8%8D%E5%9C%A8%E8%AF%8D%E8%A1%A8%22%5D%0A%20%20A%20--%3E%20A2%5B%221%20%E4%B8%AA%20token%EF%BC%8C%E9%95%BF%E5%BA%A6%E5%87%A0%E4%B9%8E%E6%97%A0%E6%8D%9F%E8%80%97%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E6%8B%86%20UTF-8%EF%BC%9A3-4%20%E4%B8%AA%E5%AD%97%E8%8A%82%20token%22%5D%0A%20%20A2%20--%3E%20CMP%5B%22%E8%A6%86%E7%9B%96%E7%9B%B8%E5%90%8C%EF%BC%8C%E4%BB%A3%E4%BB%B7%E4%B8%8D%E5%90%8C%EF%BC%9A%E5%9B%9E%E9%80%80%E5%AD%97%E7%AC%A6%E8%AE%A9%20fertility%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20B2%20--%3E%20CMP%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l('<p><span class="marginnote">「fertility」可以理解成「一个字平均要花几个 token」：常见英文单词约 1 个 token 就装下，而走字节回退的生僻字或 emoji 一个要拆 3-4 个。同样 100 字的输入，fertility 高的文本会多占几倍的上下文窗口和计算量——这就是「覆盖换长度」的具体账单。</span></p><p><span class="marginnote">字节回退与 GPT-2 的「全部从字节起步」不是同一设计。前者是字符表为主、未见才拆字节；后者是词表从一开始就长在字节上。LLaMA 一类 SentencePiece 词表走的是前者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练词表时保留 256 个字节符号（常写成 <code>&lt;0x00&gt;</code>…<code>&lt;0xFF&gt;</code>），再在上面叠加从语料学到的多字节子词。切分时：优先用普通子词匹配当前跨度；若当前码点不在表里，或子词匹配失败，就把该码点的 UTF-8 字节依次换成字节符号。解码时先把字节符号拼回字节串，再按 UTF-8 解释；若字节序列非法，实现必须定义是替换、丢弃还是报错。</p><p>LLaMA 的公开词表带字节回退，因此能吃代码、拉丁扩展、偶发中日韩，而不必在 32k 词表里为每个 CJK 字符占位。常见字仍作为整字符或短合并存在，罕见字走字节。这比纯字节 BPE 更省常见文本的长度，又比纯字符表少 UNK。</p><h3 id="回退必须是确定性的" tabindex="-1">回退必须是确定性的 <a class="header-anchor" href="#回退必须是确定性的" aria-label="Permalink to &quot;回退必须是确定性的&quot;">​</a></h3><p>同一码点每次必须拆成同一串字节符号，否则嵌入无法对齐。不要在回退路径上做 Unigram 采样：采样只作用于表内子词；一旦落到字节，路径应唯一。训练语料里若大量触发回退，说明词表构建时字符覆盖不够，应回头加语料或加合并，而不是指望模型在三字节碎片上学汉字。</p><p><span class="marginnote">损坏的 UTF-8（孤立续字节、过长编码）会让回退与解码不一致。分词器应在 <a href="/llm/web-clean-dedup">网页清洗</a> 之后面对合法 Unicode；回退是兜底，不是修数据的地方。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>字节回退把开放码点集映射到固定的 256 维基底。任意字符串的「拼写路径」都在 \\(V\\) 里，离散符号的完备性被补上。模型要学的是：连续的 <code>&lt;0xE4&gt;&lt;0xB8&gt;&lt;0xAD&gt;</code> 在中文语境里常常等于「中」——这是用深度去补词表的覆盖空洞，和 ByT5 把全部建模压在字节上是同一逻辑的局部版本。</p><p><span class="marginnote">初学者容易以为 UNK 只是「少认识一个词」。实际上一个 UNK 会把那个位置的信息抹成同一个编号：模型读不出内容，也写不回原文。字节回退保证每个字符都能原样拼回，聊天里的 emoji、外文人名、代码符号才不会在输出端凭空消失——这是「无损」两个字的分量。</span></p><p>因为回退符号在语料里相对稀，它们的嵌入更新少、范数往往异常。这会在后面的 glitch token 课变成可观测的病变；本课只需记住：回退符号是合法成员，不是调试输出。</p>',12)),(t(),i(r,null,{default:a(()=>[n(E,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E5%BD%93%E5%89%8D%E8%B7%A8%E5%BA%A6%22%5D%20--%3E%20HIT%7B%22%E5%9C%A8%E6%99%AE%E9%80%9A%E8%AF%8D%E8%A1%A8%E4%B8%AD%3F%22%7D%0A%20%20HIT%20--%3E%7C%22%E6%98%AF%22%7C%20SUB%5B%22%E5%AD%90%E8%AF%8D%20token%22%5D%0A%20%20HIT%20--%3E%7C%22%E5%90%A6%22%7C%20UTF%5B%22UTF-8%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20UTF%20--%3E%20BF%5B%22256%20%E5%AD%97%E8%8A%82%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20SUB%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E5%BA%8F%E5%88%97%22%5D%0A%20%20BF%20--%3E%20OUT%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>字节回退不修复词表的语言偏见：高频语言仍占满合并名额，低频语言更多走字节，序列更长、同样上下文窗口里有效内容更少。它也不等于数字的正确切分——数字字符可能在表里，却被 BPE 焊成不规则块。下一课才处理数。</p><p>把词表扩到覆盖全部 Unicode 平面可以消灭回退，但 \\(|V|\\) 与嵌入矩阵会胀到无法接受。回退是用序列长度换词表大小。若某语言是产品主路径，应在训练语料里把它的字符变成「普通子词」，让回退只打在真正的长尾上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲正则切块；只补未见码点如何避免 UNK。</li><li>字节回退用 256 个 UTF-8 字节符号拼出任意字符，SentencePiece / LLaMA 走这条路。</li><li>它与「全程字节 BPE」不同：常见字符仍是整子词，罕见才拆字节。</li><li>回退路径必须确定；非法 UTF-8 应在清洗阶段挡掉。</li><li>覆盖换长度，低频语言会更碎，公平性留到 fertility 课。</li><li>出处：Kudo &amp; Richardson, <em>SentencePiece</em>, EMNLP 2018；Touvron et al., <em>LLaMA</em>, 2023；Radford et al., GPT-2, 2019。</li></ul>',5))])}const F=A(s,[["render",c]]);export{f as __pageData,F as default};
